// Position saved by the last successful run (active workflows only).
const saved = $getWorkflowStaticData('global').cursor;
return [{ json: { cursor: String(saved ?? $('Set your settings').first().json.startCursor) } }];

// Runs after the webhook calls: the cursor moves only once stores are delivered.
const seen = $('Keep store fields').all().map(i => Number(i.json.cursor)).filter(Number.isFinite);
if (seen.length) {
  const data = $getWorkflowStaticData('global');
  data.cursor = String(Math.max(Number(data.cursor) || 0, ...seen));
}
return [{ json: { cursor: $getWorkflowStaticData('global').cursor ?? null, stores: seen.length } }];
